<?php if($message):?><div class="msg"><?=h($message)?></div><?php endif?><?php if($error):?><div class="err"><?=h($error)?></div><?php endif?>
<?php if($runResult!==null):?><div class="card"><b>نتیجه اجرای دستی</b><div class="code"><?=h(json_encode($runResult,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></div></div><?php endif?>
<div class="grid">
<?php foreach(['nobitex'=>'Nobitex','bitpin'=>'Bitpin'] as $key=>$name):$e=$ex[$key];$p=$e['performance'];?>
<div class="card exchange"><h2 style="margin-top:0"><?=$name?></h2><div><span class="badge">API <b class="<?=$e['credentials_configured']?'ok':'bad'?>"><?=$e['credentials_configured']?'READY':'NOT SET'?></b></span><span class="badge">Bot <b class="<?=$e['bot_enabled']?'ok':'bad'?>"><?=$e['bot_enabled']?'ON':'OFF'?></b></span><span class="badge">Live <b class="<?=$e['live_execution_enabled']?'ok':'bad'?>"><?=$e['live_execution_enabled']?'ON':'OFF'?></b></span></div>
<div class="row" style="margin-top:12px"><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="exchange_bot"><input type="hidden" name="exchange" value="<?=$key?>"><input type="hidden" name="enabled" value="<?=$e['bot_enabled']?'0':'1'?>"><button class="btn <?=$e['bot_enabled']?'gray':'safe'?>"><?=$e['bot_enabled']?'خاموش کردن Bot':'روشن کردن Bot'?></button></form><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="exchange_live"><input type="hidden" name="exchange" value="<?=$key?>"><input type="hidden" name="enabled" value="<?=$e['live_execution_enabled']?'0':'1'?>"><button class="btn <?=$e['live_execution_enabled']?'gray':'safe'?>"><?=$e['live_execution_enabled']?'خاموش کردن Live':'روشن کردن Live'?></button></form><form method="post" onsubmit="return confirm('چرخه LIVE برای <?=$name?> اجرا شود؟ ممکن است سفارش واقعی ایجاد شود.');"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="run_now"><input type="hidden" name="exchange" value="<?=$key?>"><button class="btn warn">اجرای یک چرخه</button></form></div>
<div class="metrics" style="margin-top:13px"><div class="metric">PnL امروز<b><?=h(number_format((float)$p['today_realized_pnl'],8,'.',''))?></b></div><div class="metric">PnL کل<b><?=h(number_format((float)$p['total_realized_pnl'],8,'.',''))?></b></div><div class="metric">Win Rate<b><?=h($p['win_rate_percent'])?>%</b></div></div>
<?php if($e['position']):?><p><b>پوزیشن فعال:</b> <?=h($e['position']['symbol'])?> — <?=h($e['position']['status'])?> — <?=h($e['position']['amount'])?></p><?php else:?><p class="muted">پوزیشن خودکار فعالی روی این صرافی وجود ندارد.</p><?php endif?>
</div><?php endforeach?>
</div>
<div class="card"><h2 style="margin-top:0">توقف اضطراری سراسری</h2><p class="<?=$status['kill_switch']?'bad':'ok'?>"><b><?=$status['kill_switch']?'فعال — هر دو صرافی متوقف هستند':'خاموش'?></b></p><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="kill_switch"><input type="hidden" name="enabled" value="<?=$status['kill_switch']?'0':'1'?>"><button class="btn <?=$status['kill_switch']?'safe':'danger'?>"><?=$status['kill_switch']?'برداشتن توقف اضطراری':'توقف اضطراری هر دو صرافی'?></button></form></div>
<div class="card"><h2 style="margin-top:0">تنظیمات مشترک استراتژی و ریسک</h2><p class="muted">این تنظیمات برای هر دو ربات استفاده می‌شود؛ روشن/خاموش بودن هر صرافی مستقل است.</p><form method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="save_settings"><div class="fields"><div class="field"><label>Quote Asset</label><select name="quote_asset"><option value="USDT" <?=$settings['quote_asset']==='USDT'?'selected':''?>>USDT</option><option value="IRT" <?=$settings['quote_asset']==='IRT'?'selected':''?>>IRT</option></select></div><div class="field"><label>Risk Profile</label><select name="risk_profile"><option value="safe" <?=$settings['risk_profile']==='safe'?'selected':''?>>Safe</option><option value="balanced" <?=$settings['risk_profile']==='balanced'?'selected':''?>>Balanced</option><option value="aggressive" <?=$settings['risk_profile']==='aggressive'?'selected':''?>>Aggressive</option></select></div><div class="field"><label>درصد سرمایه هر ورود</label><input type="number" step="0.1" min="0.5" max="20" name="position_percent" value="<?=h($settings['position_percent'])?>"></div><div class="field"><label>حداکثر مواجهه %</label><input type="number" step="0.1" min="1" max="25" name="max_position_percent" value="<?=h($settings['max_position_percent'])?>"></div><div class="field"><label>Stop Loss %</label><input type="number" step="0.1" min="0.5" max="15" name="stop_loss_percent" value="<?=h($settings['stop_loss_percent'])?>"></div><div class="field"><label>Take Profit %</label><input type="number" step="0.1" min="0.5" max="50" name="take_profit_percent" value="<?=h($settings['take_profit_percent'])?>"></div><div class="field"><label>زیان روزانه %</label><input type="number" step="0.1" min="1" max="15" name="daily_loss_limit_percent" value="<?=h($settings['daily_loss_limit_percent'])?>"></div><div class="field"><label>Minimum Signal Score</label><input type="number" min="35" max="90" name="min_signal_score" value="<?=h($settings['min_signal_score'])?>"></div><div class="field"><label>Cooldown دقیقه</label><input type="number" min="1" max="1440" name="cooldown_minutes" value="<?=h($settings['cooldown_minutes'])?>"></div></div><button class="btn" style="margin-top:12px">ذخیره تنظیمات</button></form></div>
<div class="grid"><?php foreach(['nobitex'=>'Nobitex','bitpin'=>'Bitpin'] as$key=>$name):?><div class="card"><h2 style="margin-top:0">سیگنال‌های <?=$name?></h2><div class="scroll"><table><tr><th>UTC</th><th>Market</th><th>Action</th><th>Score</th><th>Executed</th></tr><?php foreach($data[$key]['signals'] as$r):?><tr><td><?=h($r['created_at'])?></td><td><?=h($r['symbol'])?></td><td><?=h($r['action'])?></td><td><?=h($r['score'])?></td><td><?=((int)$r['executed']===1)?'بله':'خیر'?></td></tr><?php endforeach?></table></div></div><?php endforeach?></div>
<div class="card"><h2 style="margin-top:0">آخرین اجرای Cron</h2><div class="code"><?=h(json_encode($status['last_run'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></div></div>
</div></body></html>
